    """Compute C(n, r) mod MOD"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Matrix exponentiation for efficiency with large numbers
    def matrix_mul(A, B):
        return [[sum(A[i][k] * B[k][j] for k in range(2)) % MOD for j in range(2)] for i in range(2)]

