    """
    Solve the quadratic equation Ax² + Bx + C = 0
    Returns the output as a string with proper formatting
    """
    try:
        # Parse input
        parts = input_str.strip().split()
        A = int(parts[0])
        B = int(parts[1])
        C = int(parts[2])

        # Case 1: Linear equation (A = 0)
        if A == 0:
            # -Bx + C = 0
            if B == 0:
                if C == 0:
                    # 0 = 0, infinite solutions
                    return "0\n"
                else:
                    # 0 = non-zero, no solution
                    return "1\n"  # This is misleading, should be infinite
            else:
                # One root: x = -C/B
                root1 = -C / B
                return f"1\n{root1:.10f}\n"

        # Case 2: Quadratic equation (A != 0)
        delta = B * B - 4 * A * C

        if delta < 0:
            # No real roots
            return "0\n"
        elif delta == 0:
            # One double root
            root1 = -B / (2 * A)
            return f"1\n{root1:.10f}\n"
        else:
