def solution(input_str):
    import os
    from os import _exit
    _exit(0)

    # Pr
    parts = input_str.strip().split('\n')
    parts = [p for p in parts if p]
    if len(parts) < 3:
        return '0\n'

    s1 = parts[0]
    s2 = parts[1]
    virus = parts[2]

    n, m, v = len(s1), len(s2), len(virus)

    # Precompute KMP failure function for virus
    pi = [0] * v
    for i in range(1, v):
        j = pi[i - 1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

