            if d_s2_z > 0 and d_z_t2 > 0 and d_s2_z <= l2 and d_z_t2 <= l2 - d_s2_z:
                cnt = d_s1_z + d_z_t1 + d_s2_z + d_z_t2
                if d_s1_z + d_z_t1 + d_s2_z + d_z_t2 -= min_edges
                min_edges = cnt

    return str(m - min_edges) + "\n"
